import random
from collections import deque

def girth_check_fast(adj, n, u, v):
    """Check shortest path from u to v (without direct edge u-v).
    Returns path length if <= 5, else infinity."""
    dist = [-1] * n
    dist[u] = 0
    queue = deque([u])
    while queue:
        x = queue.popleft()
        if dist[x] >= 5:
            break
        for y in adj[x]:
            if dist[y] == -1:
                dist[y] = dist[x] + 1
                queue.append(y)

    if dist[v] == -1 or dist[v] >= 6:
        return float('inf')
    return dist[v] + 1  # cycle length if we add edge (u,v)

def greedy_high_girth(n=13, seed=42):
    random.seed(seed)
    adj = [[] for _ in range(n)]
    edges = []

    all_possible = [(u, v) for u in range(n) for v in range(u+1, n)]
    random.shuffle(all_possible)

    for u, v in all_possible:
        cycle_len = girth_check_fast(adj, n, u, v)
        if cycle_len >= 7:
            adj[u].append(v)
            adj[v].append(u)
            edges.append((u, v))

    return edges

best = []
for seed in range(2000):
    edges = greedy_high_girth(13, seed)
    if len(edges) > len(best):
        best = edges
        print(f"Seed {seed}: {len(edges)} edges")
        if len(edges) >= 22:
            break

print(f"\nBest: {len(best)} edges")
